using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Security.Cryptography;
using BfresLibrary;
using BfresLibrary.Helpers;

// Produce Hermite key VALUE / IN / OUT generated by BfresLibrary, not guessed
// by interpolating original cubic packed coefficient bytes.
if(args.Length!=2){Console.Error.WriteLine("Usage: HermiteProbe exact_original_animation.bfres output.json");return 2;}
var source=args[0];var target=args[1];
var rf=new ResFile(source);
var titles=new HashSet<string>{"Act_BookOpen_Player","Act_BookRead_Player","Act_ArrangeRemoveFtrHigh"};
var result=new List<JsonElement>();
for(int i=0;i<rf.SkeletalAnims.Count;i++) {
 var anim=rf.SkeletalAnims[i];
 if(!titles.Contains(anim.Name))continue;
 string helperJson=SkeletalAnimHelper.ToJson(anim);
 using var parsed=JsonDocument.Parse(helperJson);
 result.Add(parsed.RootElement.Clone());
}
if(result.Count!=titles.Count)
 throw new InvalidDataException("Missing actual named source FSKA animations: found "+result.Count);
var outDoc=new {
 schema="acnh303-r35-real-bfres-library-hermite-curve-values-v1",
 source_fres_sha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(source))).ToLowerInvariant(),
 source_bytes=new FileInfo(source).Length,
 animations=result,
 note="BfresLibrary SkeletalAnimHelper actual Hermite curves including Value, In, Out, rotation modes and BaseData. Renderer interpolation and matching PlayerBody skeleton still independently validated."
};
Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(target))!);
File.WriteAllText(target,JsonSerializer.Serialize(outDoc,new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine("R35_REAL_HERMITE_FSKA "+JsonSerializer.Serialize(new{animations=result.Count,names=titles}));
return 0;
